// Para cada post PUBLISHED sin afiliados, inyectar links y productos reales
const posts = $('Tomar 5 a la vez').all();
const affiliateLinks = $('Read AFFILIATE_LINKS').all().map(i => i.json);

const results = [];

for (const postItem of posts) {
  const post = postItem.json;
  let html = post.HTML_CONTENT || '';
  const niche = post.NICHE || '';

  // Filtrar links por nicho
  const nicheLinks = affiliateLinks.filter(l =>
    !l.NICHE || l.NICHE === niche || l.NICHE === 'general'
  );

  // === 1. Reemplazar placeholders de productos ===
  const products = nicheLinks.filter(l => l.TYPE === 'product').slice(0, 3);

  if (products[0]) {
    html = html.replace('<!-- PROD1_NAME -->', products[0].PRODUCT_NAME || 'Producto recomendado')
               .replace('<!-- PROD1_URL -->', products[0].AMAZON_URL || '#');
  }
  if (products[1]) {
    html = html.replace('<!-- PROD2_NAME -->', products[1].PRODUCT_NAME || 'Producto recomendado')
               .replace('<!-- PROD2_URL -->', products[1].AMAZON_URL || '#');
  }
  if (products[2]) {
    html = html.replace('<!-- PROD3_NAME -->', products[2].PRODUCT_NAME || 'Producto recomendado')
               .replace('<!-- PROD3_URL -->', products[2].AMAZON_URL || '#');
  }

  // === 2. Reemplazar placeholders de Telegram y Lead Magnet ===
  const telegramLink = nicheLinks.find(l => l.TYPE === 'telegram');
  const leadMagnet = nicheLinks.find(l => l.TYPE === 'lead_magnet');

  if (telegramLink) {
    html = html.replace('<!-- TELEGRAM_URL -->', telegramLink.AMAZON_URL || '#')
               .replace('<!-- TELEGRAM_NAME -->', telegramLink.PRODUCT_NAME || 'Nuestra comunidad');
  }
  if (leadMagnet) {
    html = html.replace('<!-- LEAD_MAGNET_URL -->', leadMagnet.AMAZON_URL || '#')
               .replace('<!-- LEAD_MAGNET_NAME -->', leadMagnet.PRODUCT_NAME || 'Guía gratuita');
  }

  // === 3. Inyección de keywords en texto libre (máx 2 links adicionales) ===
  const keywordLinks = nicheLinks.filter(l => l.TYPE === 'keyword' && l.KEYWORD);
  let injectedCount = 0;
  for (const kl of keywordLinks) {
    if (injectedCount >= 2) break;
    const kw = kl.KEYWORD;
    const url = kl.AMAZON_URL;
    if (!url || !kw) continue;
    // Reemplazar primera ocurrencia de la keyword fuera de tags HTML
    const pattern = new RegExp(`(?<!<[^>]*)\\b(${kw.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')})\\b(?![^<]*>)`, 'i');
    if (pattern.test(html)) {
      html = html.replace(pattern, `<a href="${url}" rel="nofollow sponsored" target="_blank">$1</a>`);
      injectedCount++;
    }
  }

  results.push({
    json: {
      ROW_NUMBER: post.ROW_NUMBER,
      POST_ID: post.POST_ID,
      BLOG_ID: post.BLOG_ID,
      HTML_CONTENT_UPDATED: html,
      TITLE: post.TITLE
    }
  });
}

return results;
